UPDATE ar_ling_root_asl SET is_primary = CASE WHEN id = 'ASL:نسو:khalil_kitab_ayn' THEN 1 ELSE 0 END WHERE root_norm = 'نسو';
UPDATE ar_ling_root_asl SET note_md = coalesce(note_md || ' ', '') || 'Primary: Seven books agree: نِسَاء / نِسْوَة is the plural of ''woman'', from a different word; al-Khalīl gives it under its own heading, apart from نسي, and is the earliest.' WHERE id = 'ASL:نسو:khalil_kitab_ayn';
UPDATE ar_ling_root_asl SET root_id = (SELECT r.id FROM ar_ling_roots r WHERE r.root_normalized = ar_ling_root_asl.root_norm) WHERE root_id IS NULL AND root_norm IN ('بين', 'حقق', 'حيي', 'ريب', 'عذر', 'غرر', 'نسو');
-- Rows that are not an aṣl of the root: Ibn Fāris has no نسو entry — the row carried his نسي text (rejected, kept).
UPDATE ar_ling_root_asl SET status = 'rejected', is_primary = 0, note_md = coalesce(note_md || ' ', '') || 'Rejected (0153): Ibn Fāris has no نسو entry; this was his نسي text.' WHERE id = 'ASL:نسو:maqayis_lugha';
-- The Jamhara's عذر group sits in the weak-letter bin (خوو …): re-keyed so the block view finds it under عذر.
INSERT OR REPLACE INTO ar_ling_lexicon_block_rekey (block_id, root_norm, root_norm_canonical, method)
SELECT id, root_norm, 'عذر', 'manual' FROM ar_ling_lexicon_block WHERE id = 'blk_jam_e25abc4f69ebbd15';
